ALTER TABLE citas ADD COLUMN total NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(total>=0);
ALTER TABLE citas ADD COLUMN duracion_minutos INTEGER NOT NULL DEFAULT 30 CHECK(duracion_minutos BETWEEN 30 AND 480);
ALTER TABLE citas ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
CREATE TABLE cita_detalles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_cita BIGINT NOT NULL REFERENCES citas(id),id_prestacion BIGINT NOT NULL,nombre VARCHAR(100) NOT NULL,precio NUMERIC(10,2) NOT NULL CHECK(precio>=0),duracion_minutos INTEGER NOT NULL CHECK(duracion_minutos BETWEEN 30 AND 240),UNIQUE(id_cita,id_prestacion));
